-- 2026-10-16 owner: B2 Muendlich Teil 3 topic 'Sonderausstellung im Museum' (Tunisia list). ROLLBACK: delete from public.muendlich_materials where teil = 3 and level = 'TELC_B2' and title = 'Eröffnungsveranstaltung für eine Sonderausstellung im Museum planen';
insert into public.muendlich_materials (teil, category, level, title, body_text, theme_category, difficulty_level, position, sort_order, source_pdf, is_unassigned_center, is_free_sample, speaking_toolbox)
select 3, 'themen', 'TELC_B2', $q$Eröffnungsveranstaltung für eine Sonderausstellung im Museum planen$q$, $q$In einem Museum in Ihrer Stadt soll es eine Sonderausstellung zum Thema „Literatur der Welt“ geben. Sie sollen bei der Planung der Eröffnungsveranstaltung helfen. Überlegen Sie, wie das Programm der Eröffnung sein könnte und was Sie alles brauchen. Planen Sie gemeinsam, was zu tun ist.$q$, 'Freizeit', 'B2', 58, 0, 'Aufgabentext vom Inhaber (2026-10-16)', false, false, $q${"struktur":[{"key":"start","demo":{"frage":"Wir sollen ja bei der Eröffnung der Sonderausstellung „Literatur der Welt“ im Museum helfen. Wo fangen wir an?","antwort":"Ich würde sagen, wir überlegen zuerst, was bei der Eröffnung alles passieren soll."}},{"key":"ziel","demo":{"frage":"Was sollte bei der Eröffnung das Hauptziel sein?","antwort":"Meiner Ansicht nach sollten wir möglichst viele Besucher für Bücher und Kulturen aus aller Welt begeistern.","reaktion":"Das halte ich für ein überzeugendes Ziel."}},{"key":"zeitpunkt","demo":{"frage":"Wann wäre der beste Zeitpunkt für die Eröffnung?","antwort":"Am sinnvollsten wäre wahrscheinlich ein Freitagabend, dann haben auch Berufstätige Zeit.","reaktion":"Das klingt nach einer vernünftigen Lösung."}},{"key":"gaeste","demo":{"frage":"Wen sollten wir zur Eröffnung einladen?","antwort":"Ich würde vorschlagen, neben Schulen und Buchhandlungen auch Autoren, Übersetzer und die lokale Presse einzuladen.","reaktion":"Das finde ich gut, so erreichen wir ein breites Publikum."}},{"key":"programm","demo":{"frage":"Wie könnte das Programm der Eröffnung aussehen?","antwort":"Eine Begrüßungsrede der Museumsleiterin, danach eine kurze Lesung aus Werken verschiedener Länder und zum Schluss ein Rundgang durch die Ausstellung.","reaktion":"Das wäre sicher abwechslungsreich, so bleibt es nicht bei langen Reden."}},{"key":"experten","demo":{"frage":"Sollten wir auch einen Autor oder eine Expertin als Gastredner einladen?","antwort":"Ja, das würde ich auf jeden Fall empfehlen, ein Autor könnte etwas über die Weltliteratur erzählen.","reaktion":"Das halte ich für sinnvoll, so bekommen wir fundierte Informationen."}},{"key":"essen","demo":{"frage":"Was sollten wir zu essen und trinken anbieten?","antwort":"Ich würde vorschlagen, kleine Snacks und Getränke aus verschiedenen Ländern anzubieten, passend zum Thema.","reaktion":"Das wäre eine schöne Idee, das passt gut zum Motto."}},{"key":"materialien","demo":{"frage":"Was brauchen wir alles für die Veranstaltung?","antwort":"Wir brauchen auf jeden Fall ein Mikrofon, Stühle, einen Beamer und Programmhefte für die Gäste.","reaktion":"Vielleicht sollten wir auch Namensschilder und Plakate besorgen."}},{"key":"werbung","demo":{"frage":"Wie könnten wir möglichst viele Besucher erreichen?","antwort":"Wir könnten Plakate in Bibliotheken und Schulen aufhängen und die Eröffnung in sozialen Medien bewerben.","reaktion":"Das halte ich für sinnvoll, weil wir dadurch eine größere Zielgruppe ansprechen."}},{"key":"aufgabenverteilung","demo":{"frage":"Wie könnten wir die Aufgaben möglichst effizient aufteilen?","antwort":"Ich könnte die Einladungen und die Werbung übernehmen. Würdest du dann die Technik und das Catering organisieren?","reaktion":"Ja, das übernehme ich gerne."}},{"key":"abschluss","demo":{"frage":"Dann können wir festhalten, dass wir die Eröffnung an einem Freitagabend mit Rede, Lesung und Rundgang veranstalten.","antwort":"Genau. So wird die Eröffnung ein gelungener Auftakt für die Sonderausstellung.","reaktion":"Perfekt, dann haben wir einen guten Plan."}}],"erklaerung":{"worauf_achten":["Das Programm sollte abwechslungsreich sein und nicht zu lang dauern.","Das Thema „Literatur der Welt“ sollte sich im Programm widerspiegeln, zum Beispiel durch Lesungen aus verschiedenen Ländern.","Denken Sie an Technik, Einladungen, Werbung und die Aufgabenverteilung."],"worum_geht_es":"In einem Museum in Ihrer Stadt soll es eine Sonderausstellung zum Thema „Literatur der Welt“ geben. Sie und Ihr Gesprächspartner / Ihre Gesprächspartnerin sollen bei der Planung der Eröffnungsveranstaltung helfen.","wichtige_punkte":["Wie sieht das Programm der Eröffnung aus (Rede, Lesung, Rundgang)?","Wer wird eingeladen (Gäste, Autoren, Presse)?","Was brauchen wir (Technik, Stühle, Programmhefte, Essen und Getränke)?","Wer übernimmt welche Aufgabe?"],"worum_geht_es_ar":"ستُقام في متحف بمدينتكم معرضٌ خاص بعنوان «أدب العالم». المطلوب منكم ومن شريككم في الحوار المساعدة في التخطيط لحفل الافتتاح.","was_wird_erwartet":"Sie überlegen gemeinsam, wie das Programm der Eröffnung aussehen könnte und was Sie alles dafür brauchen, und einigen sich auf einen Plan.","wichtige_punkte_ar":["كيف يبدو برنامج الافتتاح (كلمة، قراءة، جولة)؟","من سيتم دعوته (ضيوف، كتّاب، صحافة)؟","ماذا نحتاج (التقنيات، الكراسي، كتيّبات البرنامج، الطعام والمشروبات)؟","من يتولّى أي مهمة؟"],"was_wird_erwartet_ar":"تفكّران معًا في شكل برنامج الافتتاح وفي كل ما تحتاجانه لتنفيذه، ثم تتفقان على خطة."},"wortschatz":{"verben":["eröffnen","einladen","vorlesen","begrüßen","organisieren"],"woerter":["die Sonderausstellung","die Eröffnungsveranstaltung","die Lesung","der Gastredner","das Programmheft"],"adjektive":["abwechslungsreich","festlich","international","kulturell"]},"wortschatz_ar":{"verben":["يفتتح","يدعو","يقرأ بصوت عالٍ","يرحّب","ينظّم"],"woerter":["المعرض الخاص","حفل الافتتاح","القراءة الأدبية","المتحدّث الضيف","كتيّب البرنامج"],"adjektive":["متنوّع","احتفالي","دولي","ثقافي"]},"beispieldialog":[{"text":"Wir sollen ja bei der Eröffnung der Sonderausstellung „Literatur der Welt“ im Museum helfen. Wo fangen wir an?","section":"start","speaker":"A"},{"text":"Ich würde sagen, wir überlegen zuerst, was bei der Eröffnung alles passieren soll.","section":"start","speaker":"B"},{"text":"Was sollte bei der Eröffnung das Hauptziel sein?","section":"ziel","speaker":"A"},{"text":"Meiner Ansicht nach sollten wir möglichst viele Besucher für Bücher und Kulturen aus aller Welt begeistern.","section":"ziel","speaker":"B"},{"text":"Das halte ich für ein überzeugendes Ziel.","section":"ziel","speaker":"A"},{"text":"Wann wäre der beste Zeitpunkt für die Eröffnung?","section":"zeitpunkt","speaker":"A"},{"text":"Am sinnvollsten wäre wahrscheinlich ein Freitagabend, dann haben auch Berufstätige Zeit.","section":"zeitpunkt","speaker":"B"},{"text":"Das klingt nach einer vernünftigen Lösung.","section":"zeitpunkt","speaker":"A"},{"text":"Wen sollten wir zur Eröffnung einladen?","section":"gaeste","speaker":"A"},{"text":"Ich würde vorschlagen, neben Schulen und Buchhandlungen auch Autoren, Übersetzer und die lokale Presse einzuladen.","section":"gaeste","speaker":"B"},{"text":"Das finde ich gut, so erreichen wir ein breites Publikum.","section":"gaeste","speaker":"A"},{"text":"Wie könnte das Programm der Eröffnung aussehen?","section":"programm","speaker":"B"},{"text":"Eine Begrüßungsrede der Museumsleiterin, danach eine kurze Lesung aus Werken verschiedener Länder und zum Schluss ein Rundgang durch die Ausstellung.","section":"programm","speaker":"A"},{"text":"Das wäre sicher abwechslungsreich, so bleibt es nicht bei langen Reden.","section":"programm","speaker":"B"},{"text":"Sollten wir auch einen Autor oder eine Expertin als Gastredner einladen?","section":"experten","speaker":"A"},{"text":"Ja, das würde ich auf jeden Fall empfehlen, ein Autor könnte etwas über die Weltliteratur erzählen.","section":"experten","speaker":"B"},{"text":"Das halte ich für sinnvoll, so bekommen wir fundierte Informationen.","section":"experten","speaker":"A"},{"text":"Was sollten wir zu essen und trinken anbieten?","section":"essen","speaker":"B"},{"text":"Ich würde vorschlagen, kleine Snacks und Getränke aus verschiedenen Ländern anzubieten, passend zum Thema.","section":"essen","speaker":"A"},{"text":"Das wäre eine schöne Idee, das passt gut zum Motto.","section":"essen","speaker":"B"},{"text":"Was brauchen wir alles für die Veranstaltung?","section":"materialien","speaker":"A"},{"text":"Wir brauchen auf jeden Fall ein Mikrofon, Stühle, einen Beamer und Programmhefte für die Gäste.","section":"materialien","speaker":"B"},{"text":"Vielleicht sollten wir auch Namensschilder und Plakate besorgen.","section":"materialien","speaker":"A"},{"text":"Wie könnten wir möglichst viele Besucher erreichen?","section":"werbung","speaker":"A"},{"text":"Wir könnten Plakate in Bibliotheken und Schulen aufhängen und die Eröffnung in sozialen Medien bewerben.","section":"werbung","speaker":"B"},{"text":"Das halte ich für sinnvoll, weil wir dadurch eine größere Zielgruppe ansprechen.","section":"werbung","speaker":"A"},{"text":"Wie könnten wir die Aufgaben möglichst effizient aufteilen?","section":"aufgabenverteilung","speaker":"A"},{"text":"Ich könnte die Einladungen und die Werbung übernehmen. Würdest du dann die Technik und das Catering organisieren?","section":"aufgabenverteilung","speaker":"B"},{"text":"Ja, das übernehme ich gerne.","section":"aufgabenverteilung","speaker":"A"},{"text":"Dann können wir festhalten, dass wir die Eröffnung an einem Freitagabend mit Rede, Lesung und Rundgang veranstalten.","section":"abschluss","speaker":"A"},{"text":"Genau. So wird die Eröffnung ein gelungener Auftakt für die Sonderausstellung.","section":"abschluss","speaker":"B"},{"text":"Perfekt, dann haben wir einen guten Plan.","section":"abschluss","speaker":"A"}],"schema_version":3,"moegliche_fragen":["Wie lange sollte die Eröffnung dauern?","Sollen die Gäste Eintritt zahlen oder ist die Eröffnung kostenlos?","Brauchen wir eine Anmeldung, damit wir besser planen können?","Was machen wir, wenn mehr Gäste kommen als erwartet?","Sollten wir die Eröffnung auch fotografieren oder filmen?","Wer hält die Begrüßungsrede?","Sollten wir Bücher aus verschiedenen Ländern zum Anschauen auslegen?"],"moegliche_antworten_ideen":["Etwa eineinhalb bis zwei Stunden, damit es nicht zu lang wird.","Die Eröffnung sollte kostenlos sein, damit möglichst viele Besucher kommen.","Eine Anmeldeliste wäre sinnvoll, damit wir die Zahl der Gäste besser einschätzen können.","Wir könnten zusätzliche Stühle bereitstellen und einen zweiten Raum öffnen.","Ein Fotograf könnte die Eröffnung dokumentieren, das nutzen wir später für die Werbung.","Die Museumsleiterin oder ein Vertreter der Stadt könnte die Rede halten.","Ja, ausgewählte Bücher aus verschiedenen Ländern in Vitrinen auszustellen, wäre eine schöne Idee."]}$q$::jsonb
where not exists (select 1 from public.muendlich_materials where teil = 3 and level = 'TELC_B2' and title = $q$Eröffnungsveranstaltung für eine Sonderausstellung im Museum planen$q$)
returning id, title, is_unassigned_center, position;